function descendantIds(id,items,parentKey){const ids=new Set(id?[id]:[]),children=new Map();for(const x of items){if(!children.has(x[parentKey]))children.set(x[parentKey],[]);children.get(x[parentKey]).push(x.id)}const pending=[...ids];while(pending.length)for(const child of children.get(pending.pop())||[])if(!ids.has(child)){ids.add(child);pending.push(child)}return ids}
function projectIds(id){return descendantIds(id,state.projects,'parentProjectId')}
function ancestors(id,items,parentKey){const byId=new Map(items.map(x=>[x.id,x])),path=[],seen=new Set();while(id&&!seen.has(id)){seen.add(id);const item=byId.get(id);if(!item)break;path.push(item);id=item[parentKey]}return path.reverse()}
function projectPath(id){return ancestors(id,state.projects,'parentProjectId').map(p=>projectName(p.id)).join(' / ')}
function projectTree(id){const parts=[],pending=state.projects.filter(p=>p.parentProjectId===id&&!['archived','deleted'].includes(p.status)).reverse().map(p=>({p}));while(pending.length){const {p,close}=pending.pop();if(close){parts.push('</div></details></div>');continue}const children=state.projects.filter(x=>x.parentProjectId===p.id&&!['archived','deleted'].includes(x.status));parts.push('<div class=tree-node>'+action(p.name,'project-detail',p.id));if(children.length){parts.push('<details data-portfolio-detail="project:'+esc(p.id)+'"><summary>子プロジェクト '+children.length+'件</summary><div class=tree-children>');pending.push({close:true});for(const child of children.reverse())pending.push({p:child})}else parts.push('</div>')}return '<div class=hierarchy-scroll>'+parts.join('')+'</div>'}
