chatRenderer.link=function({href,tokens}){const label=this.parser.parseInline(tokens);return /^(?:https?:\/\/|mailto:|#|\/(?!\/))/i.test(href)&&!/[\u0000-\u0020\u007f]/.test(href)?'<a href="'+esc(href)+'" rel="noopener noreferrer">'+label+'</a>':label};
