const outputLabels={unregistered:'ファイルあり・未登録',empty_file:'空のファイル・未登録',not_found:'出力先にファイルなし',directory:'フォルダを指定',outside:'プロジェクト外の出力先',unavailable:'出力先を確認できません'};
