async function pollSide(){const id=sideCurrent,version=inspectorVersion;if(inspectorMode!=='side'||!id)return;try{const [picker,history]=await Promise.all([sideApi('picker'),sideApi('history',{id})]);if(version!==inspectorVersion||sideCurrent!==id||view!=='daily')return;sidePicker=picker;sideMessages=history.messages.filter(message=>message.role==='assistant'||message.role==='user'&&message.source?.kind==='user');const output=$('#side-history');if(output){const html=sideHistory();if(output.chatHtml!==html){output.innerHTML=html;output.chatHtml=html}}if(document.activeElement.id!=='side-message')updateDailyChat(dailyConversation||state.daily)}catch(error){if(version===inspectorVersion&&sideCurrent===id&&view==='daily')throw error}}
