function updateDailyChat(d,follow=false){
 if(sidePicker&&d.sessionId&&sidePicker.parentSessionId!==d.sessionId){sidePicker=null;sideCurrent=null;sideMessages=[];if(inspectorMode==='side')inspectorMode='workers';inspectorVersion++}
 if(d.workDay){state.workDay=d.workDay;state.workDayStarted=d.workDayStarted;$('#today').textContent='作業日 '+new Intl.DateTimeFormat('ja-JP',{dateStyle:'full',timeZone:'Asia/Tokyo'}).format(Date.parse(currentWorkDay()+'T12:00:00+09:00'));}
 const output=$('#daily-output'),scroll=output.scrollTop,atBottom=follow||output.scrollHeight-output.clientHeight-scroll<64,html=dailyHistory(d);
 if(output.chatHtml!==html){const active=document.activeElement,focus=active.tagName==='SUMMARY'?active.parentElement?.dataset.dailyDetail:null,opened=new Set([...output.querySelectorAll('details[data-daily-detail][open]')].map(el=>el.dataset.dailyDetail));output.innerHTML=html;output.chatHtml=html;for(const el of output.querySelectorAll('details[data-daily-detail]')){el.open=opened.has(el.dataset.dailyDetail);if(focus===el.dataset.dailyDetail)el.querySelector('summary').focus({preventScroll:true})}}
 $('#daily-status').innerHTML=dailyStatus(d);$('#daily-execution').innerHTML=executionStatus();
 if($('#daily-resources')){$('#daily-resources').dataset.mode=inspectorMode;if($('#daily-workspace'))$('#daily-workspace').dataset.inspector=inspectorMode;const back=$('#daily-resources [data-action="daily-inspector"]');if(back)back.hidden=inspectorMode!=='preview';}
 const details=$('#daily-details'),opened=[...details.querySelectorAll('details[data-daily-detail][open]')].map(e=>e.dataset.dailyDetail),active=document.activeElement,focusDetail=active.tagName==='SUMMARY'?active.parentElement?.dataset.dailyDetail:null;
 const detailHtml=dailyDetails(d);if(details.chatHtml!==detailHtml&&!(inspectorMode==='side'&&details.contains(document.activeElement)&&document.activeElement.id==='side-message')){details.innerHTML=detailHtml;details.chatHtml=detailHtml;for(const el of details.querySelectorAll('details[data-daily-detail]')){el.open=opened.includes(el.dataset.dailyDetail);if(focusDetail===el.dataset.dailyDetail)el.querySelector('summary').focus({preventScroll:true})}}
 state.daily=d;const send=$('#daily-form button[type=submit]');if(send)send.textContent=d.running?'追記を送信':'送信';$('#daily-latest').hidden=atBottom;output.scrollTop=atBottom?output.scrollHeight:scroll;
}
function todayTasks(){
 const day=currentWorkDay(),start=state.workDayStarted??Date.parse(day+'T09:00:00+09:00'),end=Date.parse(day+'T09:00:00+09:00')+86400000-1;
 const ranks=new Map((state.daily?.picks||[]).map((p,i)=>[p.taskId,i]));
 return state.tasks.filter(t=>t.actor!=='archived'&&!['reported','cancelled'].includes(t.status)&&(t.status==='done'?t.completedAt&&t.completedAt>=start&&t.completedAt<=end:t.status==='doing'||(t.planDay&&t.planDay<=day)||(t.due&&t.due<=end)||(['waiting','review'].includes(t.status)&&t.checkAt&&t.checkAt<=end))).sort((a,b)=>(ranks.get(a.id)??99)-(ranks.get(b.id)??99)||taskOrder(a,b));
}
