function option(value,label,selected){return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`}
// Native answers keep their full identity; only visible labels have a width budget.
function questionOptionLabels(options){
 const fit=(value,budget)=>{let end=Math.min(value.length,budget-3);if(value.length<=budget)return value;if(end&&/^[\uDC00-\uDFFF]$/.test(value[end]))end--;return value.substring(0,end)+'...'};
 const compact=options.map(value=>fit(value,30)),counts=new Map();for(const label of compact)counts.set(label,(counts.get(label)||0)+1);
 return options.map((value,index)=>{const prefix=counts.get(compact[index])>1?String(index+1)+'. ':'';return `<option value="${esc(value)}" title="${esc(value)}" aria-label="${esc(value)}">${esc(prefix+fit(value,30-prefix.length))}</option>`}).join('');
}
