function managerPanel(full=false){const m=state.manager;if(!m)return '';const pending=m.items.filter(i=>i.state==='pending').sort((a,b)=>(b.body.at||0)-(a.body.at||0)),done=m.sources.filter(s=>s.state==='done').length,errors=m.sources.filter(s=>s.state==='error');const items=full?filtered(pending).slice(0,60):pending.slice(0,3);return heading('履歴からの整理',`過去の抽出候補 ${pending.length}件 · 解析済み ${done} / ${m.sources.length}資料 · 最終成功 ${relative(m.status.lastSuccess)}${m.status.running?' · エージェントが整理中':''} · 読取区間 ${m.sources.reduce((n,s)=>n+(s.cursor||0),0)} / ${m.sources.reduce((n,s)=>n+(s.total||0),0)}`,state.role==='admin'?action(m.enabled?'今すぐ再整理':'自動整理を開始','manager-run'):'')+`<div class=notice>エージェントが最新記録を案件ごとに統合し、作業台帳へ登録します。過去の抽出候補は参考資料で、一件ずつの承認待ち一覧ではありません。正式締切は根拠のある登録済み情報だけを監視します。<p>統合済み ${(m.organizedProjects||[]).length}案件${m.organization?.running?' · 最新状況を整理中':''}${m.organization?.error?' · '+esc(m.organization.error):''}</p>${m.status.error?'<p class=warning>'+esc(m.status.error)+'</p>':''}${errors.length?'<p class=warning>読み取り・整理失敗 '+errors.length+'件</p>':''}${m.sources.some(s=>s.cursor<s.total)?'<p>長い履歴は分割して順に解析します。未読範囲がある間は全件確認済みになりません。</p>':''}</div><div class=panel>${items.map(i=>`<div class=row><div class=row-main><div class=row-meta>${esc(projectName(i.projectId))} ${badge(i.kind==='deadline'?'締切候補':'作業候補','warn')} · 発言 ${esc(date(i.body.at))}</div><h3>${esc(i.title)}</h3><p>${esc(i.body.goal)}</p><small>${esc(i.body.reason||'現在も必要か確認してください')}</small>${i.kind==='deadline'?'<p>'+esc(i.body.local||'日時未確定')+' '+esc(i.body.zone)+'</p>':''}</div><div class=row-actions>${action('根拠を確認','manager-evidence',i.id)}${state.role==='admin'?action('不要・対応済み','manager-dismiss',i.id):''}</div></div>`).join('')||empty(m.status.running?'履歴を整理しています':'未確認の候補はありません','未解析・読取失敗の資料がないかも確認してください。')}</div>`+(full?`<details><summary>資料ごとの解析状況（候補は検索で絞り込み・最大60件表示）</summary>${m.sources.map(s=>`<p>${esc(s.title)} — ${esc(({done:'解析済み',running:'解析中',pending:'未解析',partial:'続きの解析待ち',incomplete:'読取欠落あり',error:'失敗'})[s.state]||s.state)}${s.limited?'（分割して解析）':''} · ${s.cursor||0}/${s.total||0}区間${s.damaged?' · 破損行 '+s.damaged+'件':''}<br><small>${esc(s.error||'')} ${esc(date(s.checked))}</small></p>`).join('')}</details>${state.role==='admin'?action('計画書を追加','manager-plan')+(m.enabled?action('自動整理を停止','manager-stop'):''):''}`:action('過去の候補・解析状況を見る','manager-view'))}
