function filters(){return `<div class="filters"><input id="search" aria-label="検索" placeholder="名前で検索…" value="${esc(search)}"><select id="project-filter" aria-label="プロジェクトで絞り込む">${option('','すべてのプロジェクト',projectFilter)}${projectOptions(projectFilter)}</select></div>`}
