function deadlineRows(items){return [...items].sort((a,b)=>deadlineDay(a)-deadlineDay(b)||a.title.localeCompare(b.title,'ja')).map(d=>`<div class="row"><div class="row-main"><div class="row-meta">${esc(projectName(d.projectId))} · ${esc(d.stage)} ${d.monitor==='excluded'?badge('監視対象外','gray'):d.received?badge('受付確認済み'):badge(bands[d.band]||(d.category==='date'?'日付登録済み・時刻未記載':'予定'),d.priority===0?'danger':d.priority===1?'warn':'')}</div><h3>${esc(d.title)}</h3><div class="row-meta">${d.due?esc(date(d.due))+'（表示端末の時間）':esc(d.local||'日時未登録')+' · 時刻未確認'} · ${esc(d.zone)}</div></div><div class="row-actions">${action('詳細','deadline-detail',d.id)}${!d.received?action('編集','deadline',d.id)+(d.monitor!=='excluded'?action('対象外にする','deadline-exclude',d.id)+action('提出を記録','submission',d.id,false):''):action('受付確認を取り消す','submission',d.id)}</div></div>`).join('')||empty('締切を登録しましょう','正式な締切と出典を保存して、提出受付まで追跡できます。',action('＋ 締切を登録','deadline','',false))}
function taskRows(items,hierarchy=false){
 const ordered=[],included=new Set(items.map(t=>t.id)),children=new Map();for(const t of items){if(!children.has(t.parentId))children.set(t.parentId,[]);children.get(t.parentId).push(t)}
 const pending=items.filter(t=>!hierarchy||!included.has(t.parentId)).reverse().map(t=>[t,0]);while(pending.length){const [t,depth]=pending.pop();ordered.push([t,depth]);if(hierarchy)for(const c of [...(children.get(t.id)||[])].reverse())pending.push([c,depth+1])}
 return ordered.map(([t,depth],index)=>{
 const assigned=(state.daily?.assignments||[]).find(a=>a.taskId===t.id&&a.status!=='cancelled');
 const parent=state.tasks.find(x=>x.id===t.parentId),links=(state.taskRuns||[]).filter(x=>x.taskId===t.id),blocked=t.dependencies.filter(id=>state.tasks.find(x=>x.id===id)?.status!=='done');
 const row=`<div class="row" data-depth="${ancestors(t.id,state.tasks,'parentId').length-1}" data-task-id="${esc(t.id)}"><div class="row-main"><div class="row-meta">${esc(projectName(t.projectId))} ${(state.manager?.items||[]).some(i=>i.entityId===t.id&&i.state==='organized')?badge('エージェントが履歴から整理','gray'):''} ${badge(statuses[t.status],['waiting','review'].includes(t.status)?'warn':'')}${t.checkAt&&t.checkAt<=state.now&&['waiting','review'].includes(t.status)?badge('確認日時を経過','danger'):''}${t.status==='done'&&!t.completionEvidence?badge('旧記録・証拠未登録','warn'):''}${blocked.length?badge('前提作業 '+blocked.length+'件が未完了','warn'):''}</div>${parent?`<small title="${esc(ancestors(t.id,state.tasks,'parentId').map(x=>x.title).join(' / '))}">第${ancestors(t.id,state.tasks,'parentId').length}階層 · 親作業：${action(parent.title,'task',parent.id)}</small>`:''}<h3>${esc(t.title)}</h3><div class="row-meta">${esc(responsibility(t))}${t.due?' · 行動期限 '+esc(date(t.due)):''}</div>${t.planDay?'<div class=row-meta>作業予定：'+esc(t.planDay)+(t.planDay<currentWorkDay()&&!['done','reported','cancelled'].includes(t.status)?' · 前日以前からの持ち越し':'')+'</div>':''}${t.priorityReason?'<p class=notice>'+esc(t.priorityReason)+'</p>':''}${view==='overview'&&!['done','reported','cancelled'].includes(t.status)&&(state.daily?.picks||[]).some(p=>p.taskId===t.id)?'<p class=task-next>今日の一歩：'+esc(state.daily.picks.find(p=>p.taskId===t.id).action)+'<br><small>'+esc(state.daily.picks.find(p=>p.taskId===t.id).reason)+'</small></p>':''}${t.output?'<p>出力：'+esc(t.output)+'</p>':''}${t.nextAction?`<p class="task-next">${["done","cancelled","reported"].includes(t.status)?"記録した行動":"次の行動"}：${esc(t.nextAction)}</p>`:''}${['waiting','review'].includes(t.status)?`<div class="row-meta">${esc(waitNames[t.waitReason]||'待ち理由未登録')} · ${esc(t.waitingFor||'待ち先未登録')}<br>次回確認：${esc(date(t.checkAt))}</div>`:''}${t.dependencies.length?`<small>前提：${t.dependencies.map(id=>{const d=state.tasks.find(x=>x.id===id);return esc(d?.title||id)+'（'+esc(statuses[d?.status]||'不明')+'）'}).join('、')}</small>`:''}${t.body||t.inputs||t.completionCriteria||t.completionEvidence||t.canonicalTarget?`<details><summary>作業内容・完了条件・証拠</summary>${t.body?'<p class=task-body>'+esc(t.body)+'</p>':''}${t.inputs?'<p>入力資料：'+esc(t.inputs)+'</p>':''}<p>完了条件：${esc(t.completionCriteria||'未登録')}</p><p>正本・作業先：${esc(t.canonicalTarget||'未登録')}</p><p>確認記録：${esc(t.completionEvidence||'未登録')}</p><small>記入された確認記録です。外部での受付を自動検証するものではありません。</small></details>`:''}</div><div class="row-actions">${assigned?.runId&&state.role==='admin'?action('担当エージェントを開く','pi-chat',assigned.runId,false):''}${assigned?.workspace?action('差分・成果物','assignment-changes',assigned.id):''}${links.length?action('関連セッション '+links.length+'件','task-sessions',t.id):''}${(state.manager?.items||[]).some(i=>i.entityId===t.id)?action('登録の根拠','task-evidence',t.id):''}${!assigned&&state.role==='admin'&&t.actor!=='archived'&&!['done','cancelled','reported'].includes(t.status)?action('エージェントで作業する','task-pi',t.id,false):''}${!['done','cancelled','reported'].includes(t.status)?(t.planDay===currentWorkDay()?'':action('今日やる','task-today',t.id))+(t.status!=='doing'&&['self','pi'].includes(t.actor)&&!blocked.length&&!state.tasks.some(c=>c.parentId===t.id&&!['done','reported','cancelled'].includes(c.status))?action('着手する','task-start',t.id):'')+action('完了にする','task-complete',t.id):''}${action('子作業を追加','child-task',t.id)}${action('編集','task',t.id)}</div></div>`;
 const count=hierarchy?(children.get(t.id)||[]).length:0;return row+(count?'<details data-portfolio-detail="task:'+esc(t.id)+'"><summary>子作業 '+count+'件</summary><div class=tree-children>':'')+(hierarchy?'</div></details>'.repeat(Math.max(0,depth-(ordered[index+1]?.[1]||0))):'');
 }).join('')||empty('該当する作業はありません','作業と次の行動を登録すると、ここに表示されます。');
}
