function runRows(items){return items.map(r=>{const stale=Date.now()-r.observed>90000;return `<div class="row"><div class="row-main"><div class="row-meta">${badge(r.source==='Pi'?'保存セッション':r.source)} ${esc(projectName(r.projectId))}</div><h3>${esc(r.title)}</h3><div class="row-meta">${badge(statuses[r.status]||r.status,r.status==='running_observed'?'warn':'gray')} ${stale&&r.status==='running_observed'?badge('その後の状態は未確認','gray'):''}<span>最終活動 ${esc(relative(r.observed))}</span></div><small>${esc(r.detail)}</small><div class=task-links>${(state.taskRuns||[]).filter(x=>x.runId===r.id).map(x=>action(state.tasks.find(t=>t.id===x.taskId)?.title||'関連作業','task',x.taskId)).join('')}</div></div><div class="row-actions">${r.source==='Codex'?`<a href="codex://threads/${encodeURIComponent(r.threadId)}">Codexで開く</a>`:''}${action('関連付け','binding',r.id)}${state.role==='admin'?(r.source==='Codex'?action('会話を引き継ぐ','handoff',r.id):state.managedPi.includes(r.id)?action('エージェントで続ける','pi-chat',r.id):''):''}</div></div>`}).join('')||empty('接続先の作業がまだありません','接続・通知でエージェントの保存先を指定できます。')}
