function piChatBody(r){const messages=(r.messages||[]).filter(m=>m.text?.trim()),replies=messages.filter(m=>m.role==='assistant'),latest=replies.at(-1);return `<p role="status">${esc(({idle:'待機中',running:'作業中',submitting:'送信中',retrying:'再試行中',waiting_input:'回答待ち',error:'実行失敗'})[r.status]||r.status)} · ${esc(r.model||'')} ${esc(r.activity||'')}</p>${r.error?'<p class=warning>'+esc(r.error)+'</p>':''}${r.notice?'<p>'+esc(r.notice)+'</p>':''}<section class="chat-answer"><div class="chat-author">担当エージェントの最新の回答</div><div class="chat-text">${esc(latest?.text||'応答を待っています…')}</div></section><details data-pi-detail="history"><summary>指示・以前の会話（${messages.length}件）</summary>${messages.filter(m=>m!==latest).map(m=>`<section class="${m.role==='user'?'chat-user':'chat-answer'}"><small>${m.role==='user'?'指示':'エージェント'}</small><div class=chat-text>${esc(m.text)}</div></section>`).join('')}</details>`+(r.operations||[]).map(o=>`<small>送信記録：${esc(({submitting:'送信中',accepted:'受理済み',completed:'今回の実行終了',uncertain:'結果不明・要照合',rejected:'拒否',reviewed:'本人が結果を照合済み'})[o.status]||o.status)} · ${esc(date(o.created))} ${esc(o.error||'')}${o.status==='uncertain'?action('結果を照合して記録','pi-resolve',o.requestId):''}</small>`).join('')}
