setInterval(()=>{if(!document.hidden&&state)refresh(false).catch(()=>{if($('#shell').hidden)return;$('#health').textContent='接続が切れました。表示は最後に取得した情報です。'})},10000);
setInterval(async()=>{const id=chatId,version=dialogVersion;if(!id||!$('#editor').open||!$('#pi-output'))return;try{const r=await api('pi-state?id='+encodeURIComponent(id));if(version!==dialogVersion||chatId!==id)return;const opened=[...$('#pi-output').querySelectorAll('details[open]')].map(d=>d.dataset.piDetail);$('#pi-output').innerHTML=piChatBody(r);for(const name of opened){const detail=$('#pi-output').querySelector('[data-pi-detail="'+name+'"]');if(detail)detail.open=true}const q=r.question;if(q?.id!==displayedQuestion?.id||q?.message!==displayedQuestion?.message){displayedQuestion=q?{...q,sessionId:id}:null;$('#pi-question').innerHTML=q?`<div class=notice><p>${esc(q.title||'エージェントからの確認')}</p><p>${esc(q.message||'')}</p>${q.method==='confirm'?'<label>回答<select id=pi-confirm-value><option value=no>いいえ</option><option value=yes>はい</option></select></label>':q.method==='select'?`<label>回答<select id=pi-answer-value>${questionOptionLabels(q.options||[])}</select></label>`:`<label>回答<textarea id=pi-answer-value>${esc(q.prefill||'')}</textarea></label>`}</div>`:'';$('#pi-question-actions').hidden=!q;$('#pi-question-actions').innerHTML=q?action('質問を取消','pi-cancel',q.id)+action('この質問に回答','pi-answer',q.id,false):'';$('#cancel-dialog').hidden=!!q;$('#edit-form button[type=submit]').hidden=!!q;const composer=$('#edit-form textarea[name=message]')?.closest('label');if(composer)composer.hidden=!!q;if(q){$('#pi-question').scrollIntoView({block:'nearest'});$('#pi-answer-value')?.focus({preventScroll:true})}}}catch(e){if(version===dialogVersion&&$('#pi-output'))$('#pi-output').textContent=e.message}},2000);

setInterval(async()=>{const epoch=authVersion;if(!state||view!=='daily'||!$('#daily-output'))return;try{const d=await api('daily-state');if(epoch===authVersion&&view==='daily'&&$('#daily-output')){dailyConversation=d;updateDailyChat(d);$('#daily-error').textContent=''}await pollSide();const id=inspectorRun,version=inspectorVersion;if(id){const r=await api('pi-state?id='+encodeURIComponent(id));if(version===inspectorVersion&&view==='daily'&&$('#worker-output'))$('#worker-output').innerHTML=workerHistory(r)}}catch(e){if(epoch===authVersion&&view==='daily'&&$('#daily-error'))$('#daily-error').textContent=e.message}},2000);

document.addEventListener('change',e=>{if(e.target.id?.startsWith('worker-model-')||e.target.hasAttribute?.('data-fallback-model'))modelSettingsDirty=true;if(e.target.id==='worker-model-target'){const m=(e.target.value.startsWith('role:')?state.workerModels?.roles?.[e.target.value.slice(5)]:e.target.value.startsWith('category:')?state.workerModels?.categories?.[e.target.value.slice(9)]:state.workerModels?.tasks?.[e.target.value])||state.workerModels?.default;if(m){$('#worker-model-value').value=JSON.stringify({provider:m.provider,model:m.model});$('#worker-model-effort').value=m.reasoningEffort;}drawFallbacks(assignedFallbacks(e.target.value));}});
